/** The script policy is generated by Angular autoCsp; do not override it here. */
export function securityHeaders(settings) {
  const connections = settings.mode === 'supabase' ? ` 'self' ${settings.url}` : " 'self'";
  const policy = [
    "base-uri 'self'",
    "object-src 'none'",
    "frame-ancestors 'none'",
    "frame-src 'none'",
    "form-action 'self'",
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data:",
    "font-src 'self'",
    `connect-src${connections}`,
  ].join('; ');

  // These patterns do not overlap for Cache-Control; Pages joins duplicate headers.
  const documents = [
    '/',
    '/index.html',
    '/login',
    '/players',
    '/players/*',
    '/session/*',
    '/clubhouse/*',
  ];

  return [
    '/*',
    `  Content-Security-Policy: ${policy}`,
    '  X-Frame-Options: DENY',
    '  X-Content-Type-Options: nosniff',
    '  Referrer-Policy: no-referrer',
    '  Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=()',
    '  X-Robots-Tag: noindex, nofollow',
    '',
    ...documents.flatMap((route) => [route, '  Cache-Control: no-cache', '']),
    '/app-config.json',
    '  Cache-Control: no-store',
    '',
    '/*.js',
    '  Cache-Control: public, max-age=31536000, immutable',
    '',
    '/*.css',
    '  Cache-Control: public, max-age=31536000, immutable',
    '',
  ].join('\n');
}
